Here is the root cause:
The protocol version validation was moved to a point after the session reference was acquired, but the error path did not release that reference, causing a memory leak.

Here is the patch:
 /* UDP encapsulation receive handler. See net/ipv4/udp.c for details. */
 int l2tp_udp_encap_recv(struct sock *sk, struct sk_buff *skb)
 {
 	struct l2tp_session *session = NULL;
 	struct l2tp_tunnel *tunnel = NULL;
 	struct net *net = sock_net(sk);
 	unsigned char *ptr, *optr;
 	u16 hdrflags;
 	u16 version;
 	int length;

 	/* UDP has verified checksum */

 	/* UDP always verifies the packet length. */
 	__skb_pull(skb, sizeof(struct udphdr));

 	/* Short packet? */
 	if (!pskb_may_pull(skb, L2TP_HDR_SIZE_MAX))
 		goto pass;

 	/* Point to L2TP header */
 	optr = skb->data;
 	ptr = skb->data;

 	/* Get L2TP header flags */
 	hdrflags = ntohs(*(__be16 *)ptr);

 	/* Get protocol version */
 	version = hdrflags & L2TP_HDR_VER_MASK;

 	/* Get length of L2TP packet */
 	length = skb->len;

 	/* If type is control packet, it is handled by userspace. */
 	if (hdrflags & L2TP_HDRFLAG_T)
 		goto pass;

 	/* Skip flags */
 	ptr += 2;

 	if (version == L2TP_HDR_VER_2) {
 		u16 tunnel_id, session_id;

 		/* If length is present, skip it */
 		if (hdrflags & L2TP_HDRFLAG_L)
 			ptr += 2;

 		/* Extract tunnel and session ID */
 		tunnel_id = ntohs(*(__be16 *)ptr);
 		ptr += 2;
 		session_id = ntohs(*(__be16 *)ptr);
 		ptr += 2;

 		session = l2tp_v2_session_get(net, tunnel_id, session_id);
 	} else {
 		u32 session_id;

 		ptr += 2;	/* skip reserved bits */
 		session_id = ntohl(*(__be32 *)ptr);
 		ptr += 4;

 		session = l2tp_v3_session_get(net, sk, session_id);
 	}

 	if (!session || !session->recv_skb) {
 		if (session)
 			l2tp_session_put(session);

 		/* Not found? Pass to userspace to deal with */
 		goto pass;
 	}

 	tunnel = session->tunnel;

 	/* Check protocol version */
-	if (version != tunnel->version)
+	if (version != tunnel->version) {
+		l2tp_session_put(session);
 		goto invalid;
+	}

 	if (version == L2TP_HDR_VER_3 &&
 	    l2tp_v3_ensure_opt_in_linear(session, skb, &ptr, &optr)) {
 		l2tp_session_put(session);
 		goto invalid;
 	}

 	l2tp_recv_common(session, skb, ptr, optr, hdrflags, length);
 	l2tp_session_put(session);

 	return 0;

 invalid:
 	atomic_long_inc(&tunnel->stats.rx_invalid);

 pass:
 	/* Put UDP header back */
 	__skb_push(skb, sizeof(struct udphdr));

 	return 1;
 }
 EXPORT_SYMBOL_GPL(l2tp_udp_encap_recv);


